export const SPEC_DESIGN_BASELINES: SpecBaselineRow[] = [
{"id":"BD-01 문서 기준","criterion":"설계 고정 공식 Control / Quality / Governance+Monitoring / Vehicle 및 Knowledge Foundation, C01~C49, UI01~UI30, FRI-001~184를 보존한다. 본문 3종에 정본을 배정하고 Topology·속성 사전·AAOS 도면은 연결 부속자료로 유지한다."},
{"id":"BD-02 Unleash 사용 위치","criterion":"설계 고정 Unleash는 설정 작성·수집 원천이다. FP가 정규화·독립 품질 검토·운영 허가·서명 발행을 소유한다. 도구 저장·Admin Applied·Frontend true는 차량 실행 권한이 아니다."},
{"id":"BD-03 제품 버전","criterion":"호환성 대상 고정 생산 승인 보류 서버 v8.2.0 OSS 화면을 호환성 검토 대상으로 고정한다. v8.0.0 commit 7e69bb26a137a38bb420c3c3238888cb6c411227, Node SDK 6.12.1, Provider 1.0.0, OpenFeature JS 1.23.0은 기존 분석 기준이다. 8.2 제품·SDK의 실행 파일 dig"},
{"id":"BD-04 에디션과 배포 방식","criterion":"설계 고정 외부 확인 대기 초기 설계는 Enterprise 전용 기능에 의존하지 않는다. 서버는 비수정 공식 OSS 컨테이너를 우선 후보로 선정한다. 실제 digest·라이선스 파일·보안 점검·이용 형태를 확인해야 도입 기준선이 된다. Enterprise 구매·가격·SLA는 미승인이다."},
{"id":"BD-05 Edge","criterion":"초기 범위 제외 초기 필수 배치에서 Unleash Edge를 제외한다. FP 서명 저장소와 차량 캐시를 사용한다. 향후 서버 확장용 Edge는 별도 선택한다. OSS Edge의 2026-12-31 EOL을 장기 유지 대상의 근거로 사용하지 않는다."},
{"id":"BD-06 식별과 소유","criterion":"설계 고정 FeatureVersion은 0..N ControlPoint를, 각 제어점은 0..N FlagBinding을 참조한다. 실행 시 동일 제어점·조건에서 선택된 Binding은 정확히 하나여야 한다. experimentVariant와 Vehicle Variant Coding을 별도 객체로 관리한다."},
{"id":"BD-07 국가와 구현 선택","criterion":"설계 고정 기존 체번 결정 유지 조건행 내부 AND, 행 간 OR를 유지한다. Feature 지원·상품 판매·운영 허가·실제 대상은 동일 코드 사전의 정확 버전을 참조한다. 동일 조건에서 다른 구현이 중복 선택되면 CONFIG_CONFLICT이다. 공식 체번·국가별 상품 ID 정책을 이번 작업으로 승인하지 않는다."},
{"id":"BD-08 지원 프로파일","criterion":"설계 고정 FP-VEHICLE-BOOL-1은 boolean 제어에 한정한다. 도구 기본 ON/OFF, flexibleRollout의 0/100%, 명시적 17개 제약 연산자와 불변 Segment만 정규화 대상으로 허용한다. 중간 비율·부모 Flag·실험 Variant·레거시 전략은 해당 호환성 증거가 등록될 때 별도 프로파일로 허용한다. 미지원 입력을 삭제"},
{"id":"BD-09 부분 출시","criterion":"설계 고정 초기 P0 부분 출시는 C15의 FP-COHORT-1로 대상 목록을 고정한다. Unleash MurmurHash의 결과와 같다고 주장하지 않는다. vendor 중간 비율 이관은 별도 동등성 검증을 요구하며 자동 변환하지 않는다."},
{"id":"BD-10 변경과 승인","criterion":"설계 고정 독립 QualityAssessment와 G+M OperationalAuthorization을 ChangeSetHash에 결속한다. 작성자의 동일 principal·위임 체인을 통한 자기 승인·발행 허가를 금지한다. 긴급 예외도 범위·기간·사유·사후 검토 책임을 결속한다."},
{"id":"BD-11 실행과 안전","criterion":"설계 고정 적합성 검증 대기 차량에는 서명 Snapshot, 네트워크 수집이 차단된 Repository, SnapshotLease, FP facade, OEM Local Guard가 필요하다. 신규 활성화 HOLD와 실행 중 안전 전이는 구분한다. Guard의 시간·축소·정지 방식은 승인된 기능별 SafeTransitionProfile이 결정한다."},
{"id":"BD-12 성공과 관측","criterion":"설계 고정 필수 ECU의 동일 publication·policyHash·FeatureVersion·현재 boot·최신 sequence·유효 readback이 모두 일치해야 CONFIRMED이다. ACK·평가·노출 횟수는 실제 적용 증거가 아니다. COMMIT 표기는 분산 원자 commit 보장이 아니다."},
{"id":"BD-13 보안과 개인정보","criterion":"설계 고정 운영 수치 확인 대기 읽기 수집 자격증명·관리 API·서명키를 분리한다. 브라우저에는 세션과 CSRF 보호만 제공하며 비밀 원문은 저장하지 않는다. Impression은 기본 OFF, 외부 raw Context 전송은 불허한다. 보존 기간·지역·개인정보 처리 정책은 승인 프로파일이 없으면 외부 전송을 차단한다."},
{"id":"BD-14 구현과 검증 상태","criterion":"설계 고정 본 개정의 완료 범위는 상세 설계·기계 판독 계약·UI 검토 동작·정적/예제 검증이다. 실제 Unleash 통합, 서명키/HSM, SDK 언어별 회귀, SIL/HIL/실차 및 사용자 인수는 독립 증적을 요구한다."}
];

